/**
 * The Little Robe
 * ---------------
 * Each year Hannah weaves a little robe and brings it to Samuel at Shiloh as he grows in the Lord's presence. Stage: a loom at work, a tiny linen robe, the boy in a linen ephod at the tabernacle door; a mother's hands, a child's growing frame; warm, domestic light.
 *
 * Palette 0x1a2a14 → 0x060402 · light: ember · hero: pillar
 *
 * Generated by scripts/add-shot-scenes.mjs from the act data and
 * the mood board in ../../art/. Composition follows the kit in
 * ./hannah-kit.js.
 */

import { THREE, createScene, temple, column, house, pillar, person } from './hannah-kit.js';

const BG = 0x1a2a14;
const GROUND = 0x060402;

export function build(group) {
    const W = createScene(group, { seed: 3769540982, bg: BG, fogNear: 45, fogFar: 180 });

    /* light — ember */
    W.lights({ sky: 0x3a2418, gnd: 0x1a0e08, hemi: 0.4, sun: 0xff7a30, sunI: 0.7, sunPos: [20, 26, 30] });

    W.stars(90, 150, [0xf0e0c8, 0xd8c0a0], 0.7);
    W.disc([0, 34, -150], 14, 0xff8a30, 0.12);

    /* ground */
    W.ground(260, 260, 0, 0, 0x060402, { amp: 0.6, j: 0.3, flat: 30, rise: (x, z) => Math.sin(x * 0.05) * Math.cos(z * 0.04) * 1.2 });

    /* temple: colonnade and glowing doorway */
    const templeG = W.grp(group, [0, 0, -46], { name: 'temple', r: [0, -0.09, 0] });
    temple(W, templeG, 0, 0, 0, 1.1, { stone: 0x070402, trim: 0x121d0e });
    W.backdrop(templeG);

    /* house: mud-brick walls, flat roof, door */
    house(W, group, 15, 0, -16, 1.0 + W.r() * 0.3, { mud: 0x060402 });

    /* hero: the standing stone */
    pillar(W, group, 0, 0, 0, 1.15, { stone: 0x060402 });
    W.disc([0, 6, -12], 5, 0x22371a, 0.3);

    /* figures */
    person(W, group, [-5, 0, 5], { robe: 0x8a6a44, head: 'wrap', wrap: 0x1e3017, wrapTrim: 0x121d0e, beard: 'long', staff: 'planted', ry: -0.69, s: 1.20 });
    person(W, group, [4.5, 0, 6], { robe: 0x8a6a44, head: 'wrap', wrap: 0x1e3017, wrapTrim: 0x121d0e, beard: 'long', staff: 'planted', ry: 0.01, s: 1.07 });

    return W.finish();
}

export default { build };
